package com.monika.studentmanagementapi.model;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * A student record. The validation annotations below are checked
 * automatically when the controller receives @Valid input.
 */
@Schema(description = "A student record")
public class Student {

    // Generated by the server. Any id sent by the client is ignored.
    @Schema(description = "Unique id generated by the server", example = "1",
            accessMode = Schema.AccessMode.READ_ONLY)
    private Long id;

    @NotBlank(message = "name must not be blank")
    @Size(max = 100, message = "name must be at most 100 characters")
    @Schema(description = "Full name of the student", example = "Monika S.")
    private String name;

    @NotBlank(message = "email must not be blank")
    @Email(message = "email must be a valid email address")
    @Schema(description = "Email address of the student", example = "monika@example.com")
    private String email;

    @NotBlank(message = "department must not be blank")
    @Size(max = 100, message = "department must be at most 100 characters")
    @Schema(description = "Department of the student", example = "Information Technology")
    private String department;

    // Integer (not int) so a missing value is detected by @NotNull instead of silently becoming 0.
    @NotNull(message = "year is required")
    @Min(value = 1, message = "year must be between 1 and 4")
    @Max(value = 4, message = "year must be between 1 and 4")
    @Schema(description = "Year of study (1 to 4)", example = "2", minimum = "1", maximum = "4")
    private Integer year;

    public Student() {
        // Needed by Jackson to build the object from JSON.
    }

    public Student(Long id, String name, String email, String department, Integer year) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.department = department;
        this.year = year;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public String getDepartment() { return department; }
    public void setDepartment(String department) { this.department = department; }

    public Integer getYear() { return year; }
    public void setYear(Integer year) { this.year = year; }
}
